CREATE TABLE autores (id INTEGER PRIMARY KEY, nombre TEXT NOT NULL);
CREATE TABLE libros (id INTEGER PRIMARY KEY, titulo TEXT NOT NULL, anio INTEGER);
CREATE TABLE libro_autor (
  libro_id  INTEGER NOT NULL REFERENCES libros(id),
  autor_id  INTEGER NOT NULL REFERENCES autores(id),
  PRIMARY KEY (libro_id, autor_id)
);
CREATE TABLE estudiantes (id INTEGER PRIMARY KEY, nombre TEXT NOT NULL, seccion TEXT NOT NULL);
CREATE TABLE prestamos (
  id                INTEGER PRIMARY KEY,
  estudiante_id     INTEGER NOT NULL REFERENCES estudiantes(id),
  libro_id          INTEGER NOT NULL REFERENCES libros(id),
  fecha_prestamo    TEXT NOT NULL,
  fecha_devolucion  TEXT
);
